    72→import tech.pegasys.teku.spec.logic.versions.electra.helpers.MiscHelpersElectra;
    73→import tech.pegasys.teku.spec.logic.versions.electra.helpers.PredicatesElectra;
    74→import tech.pegasys.teku.spec.schemas.SchemaDefinitionsElectra;
    75→import tech.pegasys.teku.spec.schemas.SchemaDefinitionsFulu;
    76→
    77→public class MiscHelpersFulu extends MiscHelpersElectra {
    78→  private static final Logger LOG = LogManager.getLogger();
    79→
    80→  public static MiscHelpersFulu required(final MiscHelpers miscHelpers) {
    81→    return miscHelpers
    82→        .toVersionFulu()
    83→        .orElseThrow(
    84→            () ->
    85→                new IllegalArgumentException(
    86→                    "Expected Fulu misc helpers but got: "
    87→                        + miscHelpers.getClass().getSimpleName()));
    88→  }
    89→
    90→  private final Predicates predicates;
    91→  private final SpecConfigFulu specConfigFulu;
    92→  private final SchemaDefinitionsFulu schemaDefinitionsFulu;
    93→  private final BpoForkSchedule bpoForkSchedule;
    94→
    95→  public MiscHelpersFulu(
    96→      final SpecConfigFulu specConfig,
    97→      final PredicatesElectra predicates,
    98→      final SchemaDefinitionsFulu schemaDefinitions) {
    99→    super(
   100→        SpecConfigElectra.required(specConfig),
   101→        predicates,
   102→        SchemaDefinitionsElectra.required(schemaDefinitions));
   103→    this.predicates = predicates;
   104→    this.specConfigFulu = specConfig;
   105→    this.schemaDefinitionsFulu = schemaDefinitions;
   106→    this.bpoForkSchedule = new BpoForkSchedule(specConfig);
   107→  }
   108→
   109→  @Override
   110→  public Optional<MiscHelpersFulu> toVersionFulu() {
   111→    return Optional.of(this);
   112→  }
   113→
   114→  // compute_fork_digest
   115→  public Bytes4 computeForkDigest(final Bytes32 genesisValidatorsRoot, final UInt64 epoch) {
   116→    final Bytes4 forkVersion = computeForkVersion(epoch);
   117→    final Bytes32 baseDigest = computeForkDataRoot(forkVersion, genesisValidatorsRoot);
   118→    final BlobParameters blobParameters = getBlobParameters(epoch);
   119→    // Bitmask digest with hash of blob parameters
   120→    return new Bytes4(baseDigest.xor(blobParameters.hash()).slice(0, 4));
   121→  }
   122→
   123→  // get_blob_parameters
   124→  public BlobParameters getBlobParameters(final UInt64 epoch) {
   125→    return getBpoFork(epoch)
   126→        .orElse(
   127→            new BlobParameters(
   128→                specConfigFulu.getElectraForkEpoch(), specConfigFulu.getMaxBlobsPerBlock()));
   129→  }
   130→
   131→  // BPO
   132→  public Optional<BlobParameters> getBpoFork(final UInt64 epoch) {
   133→    return bpoForkSchedule.getBpoFork(epoch);
   134→  }
   135→
   136→  public Optional<BlobParameters> getNextBpoFork(final UInt64 epoch) {
   137→    return bpoForkSchedule.getNextBpoFork(epoch);
   138→  }
   139→
   140→  public Optional<Integer> getHighestMaxBlobsPerBlockFromBpoForkSchedule() {
   141→    return bpoForkSchedule.getHighestMaxBlobsPerBlock();
   142→  }
   143→
   144→  public Collection<BlobParameters> getBpoForks() {
   145→    return bpoForkSchedule.getBpoForks();
   146→  }
   147→
   148→  public UInt64 computeSubnetForDataColumnSidecar(final UInt64 columnIndex) {
   149→    return columnIndex.mod(specConfigFulu.getDataColumnSidecarSubnetCount());
   150→  }
   151→
   152→  public List<UInt64> computeDataColumnSidecarBackboneSubnets(
   153→      final UInt256 nodeId, final int groupCount) {
   154→    final List<UInt64> columns = computeCustodyColumnIndices(nodeId, groupCount);
   155→    return columns.stream().map(this::computeSubnetForDataColumnSidecar).toList();
   156→  }
   157→
   158→  public List<UInt64> computeCustodyColumnIndices(final UInt256 nodeId, final int groupCount) {
   159→    final List<UInt64> custodyGroups = getCustodyGroups(nodeId, groupCount);
   160→    return custodyGroups.stream()
   161→        .flatMap(group -> computeColumnsForCustodyGroup(group).stream())
   162→        .toList();
   163→  }
   164→
   165→  public List<UInt64> computeColumnsForCustodyGroup(final UInt64 custodyGroup) {
   166→    if (custodyGroup.isGreaterThanOrEqualTo(specConfigFulu.getNumberOfCustodyGroups())) {
   167→      throw new IllegalArgumentException(
   168→          String.format(
   169→              "Custody group (%s) cannot exceed number of groups (%s)",
   170→              custodyGroup, specConfigFulu.getNumberOfCustodyGroups()));
   171→    }
   172→
   173→    final int columnsPerGroup =
   174→        specConfigFulu.getNumberOfColumns() / specConfigFulu.getNumberOfCustodyGroups();
   175→
   176→    return IntStream.range(0, columnsPerGroup)
   177→        .mapToLong(
   178→            i -> (long) specConfigFulu.getNumberOfCustodyGroups() * i + custodyGroup.intValue())
   179→        .mapToObj(UInt64::valueOf)
   180→        .toList();
   181→  }
   182→
   183→  private UInt64 computeCustodyGroupIndex(final UInt256 nodeId) {
   184→    return bytesToUInt64(Hash.sha256(uint256ToBytes(nodeId)).slice(0, 8))
   185→        .mod(specConfigFulu.getNumberOfCustodyGroups());
   186→  }
   187→
   188→  public List<UInt64> getCustodyGroups(final UInt256 nodeId, final int custodyGroupCount) {
   189→    if (custodyGroupCount > specConfigFulu.getNumberOfCustodyGroups()) {
   190→      throw new IllegalArgumentException(
   191→          String.format(
   192→              "Custody group count (%s) cannot exceed number of groups (%s)",
   193→              custodyGroupCount, specConfigFulu.getNumberOfCustodyGroups()));
   194→    }
   195→
   196→    // Skip computation if all groups are custodied
   197→    if (custodyGroupCount == specConfigFulu.getNumberOfCustodyGroups()) {
   198→      return LongStream.range(0, custodyGroupCount).mapToObj(UInt64::valueOf).toList();
   199→    }
   200→
   201→    return Stream.iterate(nodeId, this::incrementByModule)
   202→        .map(this::computeCustodyGroupIndex)
   203→        .distinct()
   204→        .limit(custodyGroupCount)
   205→        .sorted()
   206→        .toList();
   207→  }
   208→
   209→  private UInt256 incrementByModule(final UInt256 n) {
   210→    if (n.equals(UInt256.MAX_VALUE)) {
   211→      return UInt256.ZERO;
   212→    } else {
   213→      return n.plus(1);
   214→    }
   215→  }
   216→
   217→  public UInt64 getValidatorsCustodyRequirement(
   218→      final BeaconState state, final Set<UInt64> validatorIndices) {
   219→    final UInt64 totalNodeBalance =
   220→        validatorIndices.stream()
   221→            .map(
   222→                proposerIndex -> {
   223→                  final Validator validator = state.getValidators().get(proposerIndex.intValue());
   224→                  return validator.getEffectiveBalance();
   225→                })
   226→            .reduce(UInt64.ZERO, UInt64::plus);
   227→    final UInt64 count =
   228→        totalNodeBalance.dividedBy(specConfigFulu.getBalancePerAdditionalCustodyGroup());
   229→    return count
   230→        .max(specConfigFulu.getValidatorCustodyRequirement())
   231→        .min(specConfigFulu.getNumberOfCustodyGroups());
   232→  }
   233→
   234→  public boolean verifyDataColumnSidecar(final DataColumnSidecar dataColumnSidecar) {
   235→    final int numberOfColumns = specConfigFulu.getNumberOfColumns();
   236→
   237→    if (!dataColumnSidecar.getIndex().isLessThan(numberOfColumns)) {
   238→      LOG.trace(
   239→          "DataColumnSidecar has invalid index {}. Should be less than {}",
   240→          dataColumnSidecar.getIndex(),
   241→          numberOfColumns);
   242→      return false;
   243→    }
   244→    if (dataColumnSidecar.getSszKZGCommitments().isEmpty()) {
   245→      LOG.trace("DataColumnSidecar has no kzg commitments");
   246→      return false;
   247→    }
   248→    if (dataColumnSidecar.getDataColumn().size()
   249→        != dataColumnSidecar.getSszKZGCommitments().size()) {
   250→      LOG.trace(
   251→          "DataColumnSidecar has unequal data column ({}) and kzg commitments ({}) sizes",
   252→          dataColumnSidecar.getDataColumn().size(),
   253→          dataColumnSidecar.getSszKZGCommitments().size());
   254→      return false;
   255→    }
   256→    if (dataColumnSidecar.getDataColumn().size() != dataColumnSidecar.getSszKZGProofs().size()) {
   257→      LOG.trace(
   258→          "DataColumnSidecar has unequal data column ({}) and kzg proofs ({}) sizes",
   259→          dataColumnSidecar.getDataColumn().size(),
   260→          dataColumnSidecar.getSszKZGProofs().size());
   261→      return false;
   262→    }
   263→    return true;
   264→  }
   265→
   266→  public boolean verifyDataColumnSidecarKzgProofs(
   267→      final KZG kzg, final DataColumnSidecar dataColumnSidecar) {
   268→
   269→    final List<KZGCellWithColumnId> cellWithIds =
   270→        IntStream.range(0, dataColumnSidecar.getDataColumn().size())
   271→            .mapToObj(
   272→                rowIndex ->
   273→                    KZGCellWithColumnId.fromCellAndColumn(
   274→                        new KZGCell(dataColumnSidecar.getDataColumn().get(rowIndex).getBytes()),
   275→                        dataColumnSidecar.getIndex().intValue()))
   276→            .collect(Collectors.toList());
   277→    return kzg.verifyCellProofBatch(
   278→        dataColumnSidecar.getSszKZGCommitments().stream()
   279→            .map(SszKZGCommitment::getKZGCommitment)
   280→            .toList(),
   281→        cellWithIds,
   282→        dataColumnSidecar.getSszKZGProofs().stream().map(SszKZGProof::getKZGProof).toList());
   283→  }
   284→
   285→  public boolean verifyDataColumnSidecarKzgProofsBatch(
   286→      final KZG kzg, final List<DataColumnSidecar> dataColumnSidecars) {
   287→
   288→    final List<KZGCellWithColumnId> cellWithIds =
   289→        dataColumnSidecars.stream()
   290→            .flatMap(
   291→                dataColumnSidecar ->
   292→                    IntStream.range(0, dataColumnSidecar.getDataColumn().size())
   293→                        .mapToObj(
   294→                            rowIndex ->
   295→                                KZGCellWithColumnId.fromCellAndColumn(
   296→                                    new KZGCell(
   297→                                        dataColumnSidecar.getDataColumn().get(rowIndex).getBytes()),
   298→                                    dataColumnSidecar.getIndex().intValue())))
   299→            .toList();
   300→    return kzg.verifyCellProofBatch(
   301→        dataColumnSidecars.stream()
   302→            .flatMap(sidecar -> sidecar.getSszKZGCommitments().stream())
   303→            .map(SszKZGCommitment::getKZGCommitment)
   304→            .toList(),
   305→        cellWithIds,
   306→        dataColumnSidecars.stream()
   307→            .flatMap(sidecar -> sidecar.getSszKZGProofs().stream())
   308→            .map(SszKZGProof::getKZGProof)
   309→            .toList());
   310→  }
   311→
   312→  public boolean verifyDataColumnSidecarInclusionProof(final DataColumnSidecar dataColumnSidecar) {
   313→    if (dataColumnSidecar.getSszKZGCommitments().isEmpty()) {
   314→      return false;
   315→    }
   316→    return predicates.isValidMerkleBranch(
   317→        dataColumnSidecar.getSszKZGCommitments().hashTreeRoot(),
   318→        dataColumnSidecar.getKzgCommitmentsInclusionProof(),
   319→        specConfigFulu.getKzgCommitmentsInclusionProofDepth().intValue(),
   320→        getBlockBodyKzgCommitmentsGeneralizedIndex(),
   321→        dataColumnSidecar.getBlockBodyRoot());
   322→  }
   323→
   324→  public int getBlockBodyKzgCommitmentsGeneralizedIndex() {
   325→    return (int)
   326→        BeaconBlockBodySchemaElectra.required(schemaDefinitionsFulu.getBeaconBlockBodySchema())
   327→            .getBlobKzgCommitmentsGeneralizedIndex();
   328→  }
   329→
   330→  public List<Bytes32> computeDataColumnKzgCommitmentsInclusionProof(
   331→      final BeaconBlockBody beaconBlockBody) {
   332→    return MerkleUtil.constructMerkleProof(
   333→        beaconBlockBody.getBackingNode(), getBlockBodyKzgCommitmentsGeneralizedIndex());
   334→  }
   335→
   336→  @VisibleForTesting
   337→  @Deprecated
   338→  public List<DataColumnSidecar> constructDataColumnSidecarsOld(
   339→      final SignedBeaconBlock signedBeaconBlock, final List<Blob> blobs, final KZG kzg) {
   340→    return constructDataColumnSidecars(
   341→        signedBeaconBlock.getMessage(),
   342→        signedBeaconBlock.asHeader(),
   343→        computeExtendedMatrixAndProofs(blobs, kzg));
   344→  }
   345→
   346→  public List<DataColumnSidecar> constructDataColumnSidecars(
   347→      final SignedBeaconBlock signedBeaconBlock,
   348→      final List<BlobAndCellProofs> blobAndCellProofsList,
   349→      final KZG kzg) {
   350→    return constructDataColumnSidecars(
   351→        signedBeaconBlock.getMessage(),
   352→        signedBeaconBlock.asHeader(),
   353→        computeExtendedMatrix(blobAndCellProofsList, kzg));
   354→  }
   355→
   356→  public List<DataColumnSidecar> constructDataColumnSidecars(
   357→      final SignedBeaconBlockHeader signedBeaconBlockHeader,
   358→      final SszList<SszKZGCommitment> sszKZGCommitments,
   359→      final List<Bytes32> kzgCommitmentsInclusionProof,
   360→      final List<BlobAndCellProofs> blobAndCellProofsList,
   361→      final KZG kzg) {
   362→    final List<List<MatrixEntry>> extendedMatrix =
   363→        computeExtendedMatrix(blobAndCellProofsList, kzg);
   364→    return constructDataColumnSidecars(
   365→        signedBeaconBlockHeader, sszKZGCommitments, kzgCommitmentsInclusionProof, extendedMatrix);
   366→  }
   367→
   368→  /**
   369→   * Return the full ``ExtendedMatrix``.
   370→   *
   371→   * <p>This helper demonstrates the relationship between blobs and ``ExtendedMatrix``.
   372→   *
   373→   * <p>>The data structure for storing cells is implementation-dependent.
   374→   */
   375→  public List<List<MatrixEntry>> computeExtendedMatrixAndProofs(
   376→      final List<Blob> blobs, final KZG kzg) {
   377→    return IntStream.range(0, blobs.size())
   378→        .parallel()
   379→        .mapToObj(
   380→            blobIndex -> {
   381→              final List<KZGCellAndProof> kzgCellAndProofs =
   382→                  kzg.computeCellsAndProofs(blobs.get(blobIndex).getBytes());
   383→              final List<MatrixEntry> row = new ArrayList<>();
   384→              for (int cellIndex = 0; cellIndex < kzgCellAndProofs.size(); ++cellIndex) {
   385→                row.add(
   386→                    schemaDefinitionsFulu
   387→                        .getMatrixEntrySchema()
   388→                        .create(
   389→                            kzgCellAndProofs.get(cellIndex).cell(),
   390→                            kzgCellAndProofs.get(cellIndex).proof(),
   391→                            blobIndex,
   392→                            cellIndex));
   393→              }
   394→              return row;
   395→            })
   396→        .toList();
   397→  }
   398→
   399→  public List<List<MatrixEntry>> computeExtendedMatrix(
   400→      final List<BlobAndCellProofs> blobAndCellProofsList, final KZG kzg) {
   401→    return IntStream.range(0, blobAndCellProofsList.size())
   402→        .parallel()
   403→        .mapToObj(
   404→            blobIndex -> {
   405→              final BlobAndCellProofs blobAndCellProofs = blobAndCellProofsList.get(blobIndex);
   406→              final List<KZGCell> kzgCells = kzg.computeCells(blobAndCellProofs.blob().getBytes());
   407→              final List<MatrixEntry> row = new ArrayList<>();
   408→              for (int cellIndex = 0; cellIndex < kzgCells.size(); ++cellIndex) {
   409→                row.add(
   410→                    schemaDefinitionsFulu
   411→                        .getMatrixEntrySchema()
   412→                        .create(
   413→                            kzgCells.get(cellIndex),
   414→                            blobAndCellProofs.cellProofs().get(cellIndex),
   415→                            blobIndex,
   416→                            cellIndex));
   417→              }
   418→              return row;
   419→            })
   420→        .toList();
   421→  }
   422→
   423→  @VisibleForTesting
   424→  public List<DataColumnSidecar> constructDataColumnSidecars(
   425→      final BeaconBlock beaconBlock,
   426→      final SignedBeaconBlockHeader signedBeaconBlockHeader,
   427→      final List<List<MatrixEntry>> extendedMatrix) {
   428→    if (extendedMatrix.isEmpty()) {
   429→      return Collections.emptyList();
   430→    }
   431→
   432→    final SszList<SszKZGCommitment> sszKZGCommitments;
   433→    final List<Bytes32> kzgCommitmentsInclusionProof;
   434→    if (beaconBlock.isBlinded()) {
   435→      final BlindedBeaconBlockBodyDeneb beaconBlockBody =
   436→          BlindedBeaconBlockBodyDeneb.required(beaconBlock.getBody());
   437→      sszKZGCommitments = beaconBlockBody.getBlobKzgCommitments();
   438→      kzgCommitmentsInclusionProof = computeDataColumnKzgCommitmentsInclusionProof(beaconBlockBody);
   439→    } else {
   440→      final BeaconBlockBodyDeneb beaconBlockBody =
   441→          BeaconBlockBodyDeneb.required(beaconBlock.getBody());
   442→      sszKZGCommitments = beaconBlockBody.getBlobKzgCommitments();
   443→      kzgCommitmentsInclusionProof = computeDataColumnKzgCommitmentsInclusionProof(beaconBlockBody);
   444→    }
   445→
   446→    return constructDataColumnSidecars(
   447→        signedBeaconBlockHeader, sszKZGCommitments, kzgCommitmentsInclusionProof, extendedMatrix);
   448→  }
   449→
   450→  private List<DataColumnSidecar> constructDataColumnSidecars(
   451→      final SignedBeaconBlockHeader signedBeaconBlockHeader,
   452→      final SszList<SszKZGCommitment> sszKZGCommitments,
   453→      final List<Bytes32> kzgCommitmentsInclusionProof,
   454→      final List<List<MatrixEntry>> extendedMatrix) {
   455→    if (extendedMatrix.isEmpty()) {
   456→      return Collections.emptyList();
   457→    }
   458→
   459→    final DataColumnSchema dataColumnSchema = schemaDefinitionsFulu.getDataColumnSchema();
   460→    final DataColumnSidecarSchema dataColumnSidecarSchema =
   461→        schemaDefinitionsFulu.getDataColumnSidecarSchema();
   462→    final SszListSchema<SszKZGProof, ?> kzgProofsSchema =
   463→        dataColumnSidecarSchema.getKzgProofsSchema();
   464→
   465→    final int columnCount = extendedMatrix.getFirst().size();
   466→
   467→    return IntStream.range(0, columnCount)
   468→        .mapToObj(
   469→            cellID -> {
   470→              List<MatrixEntry> columnData =
   471→                  extendedMatrix.stream().map(row -> row.get(cellID)).toList();
   472→              List<Cell> columnCells = columnData.stream().map(MatrixEntry::getCell).toList();
   473→
   474→              SszList<SszKZGProof> columnProofs =
   475→                  columnData.stream()
   476→                      .map(MatrixEntry::getKzgProof)
   477→                      .map(SszKZGProof::new)
   478→                      .collect(kzgProofsSchema.collector());
   479→              final DataColumn dataColumn = dataColumnSchema.create(columnCells);
   480→
   481→              return dataColumnSidecarSchema.create(
   482→                  UInt64.valueOf(cellID),
   483→                  dataColumn,
   484→                  sszKZGCommitments,
   485→                  columnProofs,
   486→                  signedBeaconBlockHeader,
   487→                  kzgCommitmentsInclusionProof);
   488→            })
   489→        .toList();
   490→  }
   491→
   492→  public List<DataColumnSidecar> reconstructAllDataColumnSidecars(
   493→      final Collection<DataColumnSidecar> existingSidecars, final KZG kzg) {
   494→    if (existingSidecars.size() < (specConfigFulu.getNumberOfColumns() / 2)) {
   495→      final Optional<DataColumnSidecar> maybeSidecar = existingSidecars.stream().findAny();
   496→      throw new IllegalArgumentException(
   497→          String.format(
   498→              "Number of sidecars must be greater than or equal to the half of column count, slot: %s; columns: found %s, needed at least %d",
   499→              maybeSidecar.isPresent() ? maybeSidecar.get().getSlot().toString() : "unknown",
   500→              existingSidecars.size(),
   501→              specConfigFulu.getNumberOfColumns() / 2));
   502→    }
   503→    final List<List<MatrixEntry>> columnBlobEntries =
   504→        existingSidecars.stream()
   505→            .map(
   506→                sidecar ->
   507→                    IntStream.range(0, sidecar.getDataColumn().size())
   508→                        .mapToObj(
   509→                            rowIndex ->
   510→                                schemaDefinitionsFulu
   511→                                    .getMatrixEntrySchema()
   512→                                    .create(
   513→                                        sidecar.getDataColumn().get(rowIndex),
   514→                                        sidecar.getSszKZGProofs().get(rowIndex).getKZGProof(),
   515→                                        sidecar.getIndex(),
   516→                                        UInt64.valueOf(rowIndex)))
   517→                        .toList())
   518→            .toList();
   519→    final List<List<MatrixEntry>> blobColumnEntries = transpose(columnBlobEntries);
   520→    final List<List<MatrixEntry>> extendedMatrix = recoverMatrix(blobColumnEntries, kzg);
   521→    final DataColumnSidecar anyExistingSidecar =
   522→        existingSidecars.stream().findFirst().orElseThrow();
   523→    final SignedBeaconBlockHeader signedBeaconBlockHeader =
   524→        anyExistingSidecar.getSignedBeaconBlockHeader();
   525→    return constructDataColumnSidecars(
   526→        signedBeaconBlockHeader,
   527→        anyExistingSidecar.getSszKZGCommitments(),
   528→        anyExistingSidecar.getKzgCommitmentsInclusionProof().asListUnboxed(),
   529→        extendedMatrix);
   530→  }
   531→
   532→  /**
   533→   * Return the recovered extended matrix.
   534→   *
   535→   * <p>This helper demonstrates how to apply ``recover_cells_and_kzg_proofs``.
   536→   *
   537→   * <p>The data structure for storing cells is implementation-dependent.
   538→   */
   539→  public List<List<MatrixEntry>> recoverMatrix(
   540→      final List<List<MatrixEntry>> partialMatrix, final KZG kzg) {
   541→    return IntStream.range(0, partialMatrix.size())
   542→        .parallel()
   543→        .mapToObj(
   544→            blobIndex -> {
   545→              final List<KZGCellWithColumnId> cellWithColumnIds =
   546→                  partialMatrix.get(blobIndex).stream()
   547→                      .filter(entry -> entry.getRowIndex().intValue() == blobIndex)
   548→                      .map(
   549→                          entry ->
   550→                              new KZGCellWithColumnId(
   551→                                  new KZGCell(entry.getCell().getBytes()),
   552→                                  new KZGCellID(entry.getColumnIndex())))
   553→                      .toList();
   554→              final List<KZGCellAndProof> kzgCellAndProofs =
   555→                  kzg.recoverCellsAndProofs(cellWithColumnIds);
   556→              return IntStream.range(0, kzgCellAndProofs.size())
   557→                  .mapToObj(
   558→                      kzgCellAndProofIndex ->
   559→                          schemaDefinitionsFulu
   560→                              .getMatrixEntrySchema()
   561→                              .create(
   562→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).cell(),
   563→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).proof(),
   564→                                  kzgCellAndProofIndex,
   565→                                  blobIndex))
   566→                  .toList();
   567→            })
   568→        .toList();
   569→  }
   570→
   571→  public int getSamplingGroupCount(final int custodyRequirement) {
   572→    return Math.max(custodyRequirement, specConfigFulu.getSamplesPerSlot());
   573→  }
   574→
   575→  private static <T> List<List<T>> transpose(final List<List<T>> matrix) {
   576→    final int rowCount = matrix.size();
   577→    final int colCount = matrix.getFirst().size();
   578→    final List<List<T>> ret =
   579→        Stream.generate(() -> (List<T>) new ArrayList<T>(rowCount)).limit(colCount).toList();
   580→
   581→    for (int row = 0; row < rowCount; row++) {
   582→      if (matrix.get(row).size() != colCount) {
   583→        throw new IllegalArgumentException("Different number columns in the matrix");
   584→      }
   585→      for (int col = 0; col < colCount; col++) {
   586→        final T val = matrix.get(row).get(col);
   587→        ret.get(col).add(row, val);
   588→      }
   589→    }
   590→    return ret;
   591→  }
   592→
   593→  @Override
   594→  public boolean isAvailabilityOfBlobSidecarsRequiredAtEpoch(
   595→      final UInt64 currentEpoch, final UInt64 epoch) {
   596→    return !epoch.isGreaterThanOrEqualTo(specConfigFulu.getFuluForkEpoch());
   597→  }
   598→
   599→  public boolean isAvailabilityOfDataColumnSidecarsRequiredAtEpoch(
   600→      final UInt64 currentEpoch, final UInt64 epoch) {
   601→    return currentEpoch
   602→        .minusMinZero(epoch)
   603→        .isLessThanOrEqualTo(specConfigFulu.getMinEpochsForDataColumnSidecarsRequests());
   604→  }
   605→
   606→  // compute_proposer_indices
   607→  @Override
   608→  public List<Integer> computeProposerIndices(
   609→      final BeaconState state,
   610→      final UInt64 epoch,
   611→      final Bytes32 epochSeed,
   612→      final IntList activeValidatorIndices) {
   613→    final UInt64 startSlot = computeStartSlotAtEpoch(epoch);
   614→    return IntStream.range(0, specConfigFulu.getSlotsPerEpoch())
   615→        .mapToObj(
   616→            i -> {
   617→              final Bytes32 seed =
   618→                  Hash.sha256(
   619→                      Bytes.concat(
   620→                          epochSeed.toArray(), uint64ToBytes(startSlot.plus(i)).toArray()));
   621→              return computeProposerIndex(state, activeValidatorIndices, seed);
   622→            })
   623→        .toList();
   624→  }
   625→
   626→  // initialize_proposer_lookahead
   627→  public List<UInt64> initializeProposerLookahead(
   628→      final BeaconStateElectra state, final BeaconStateAccessorsFulu beaconAccessors) {
   629→    final UInt64 currentEpoch = computeEpochAtSlot(state.getSlot());
   630→    return IntStream.rangeClosed(0, specConfigFulu.getMinSeedLookahead())
   631→        .flatMap(
   632→            i ->
   633→                beaconAccessors.getBeaconProposerIndices(state, currentEpoch.plus(i)).stream()
   634→                    .mapToInt(Integer::intValue))
   635→        .mapToObj(UInt64::valueOf)
   636→        .toList();
   637→  }
   638→}
